/**
 * Mock Mode (roadmap §3): when a provider has no API key (or is listed in
 * `MOCK_PROVIDERS`), it serves fixture JSON from `src/lib/fixtures/`.
 *
 * Mock data is tagged `isMock: true` end-to-end and must never be presented to
 * the user as real. Fixtures are generated by `pnpm db:seed`.
 */

import gametimeFixture from "@/lib/fixtures/gametime.json";
import seatgeekFixture from "@/lib/fixtures/seatgeek.json";
import stubhubFixture from "@/lib/fixtures/stubhub.json";
import ticketmasterFixture from "@/lib/fixtures/ticketmaster.json";
import tickpickFixture from "@/lib/fixtures/tickpick.json";
import vividseatsFixture from "@/lib/fixtures/vividseats.json";

import type { NormalizedQuote, ProviderId } from "./base";

interface QuoteFixture {
  providerId: string;
  minPriceCents: number | null;
  feesCents: number | null;
  allInCents: number;
  allInIsEstimate: boolean;
  listingCount: number | null;
  url: string;
  fetchedAt: string;
}

interface InventoryFixture {
  providerId: ProviderId;
  type: "inventory";
  isMock: true;
  generatedAt: string;
  quotes: Record<string, QuoteFixture>;
}

interface DeeplinkFixture {
  providerId: ProviderId;
  type: "deeplink";
  isMock: true;
  generatedAt: string;
  links: Record<string, string>;
}

const INVENTORY_FIXTURES: Partial<Record<ProviderId, InventoryFixture>> = {
  seatgeek: seatgeekFixture as unknown as InventoryFixture,
  ticketmaster: ticketmasterFixture as unknown as InventoryFixture,
};

const DEEPLINK_FIXTURES: Partial<Record<ProviderId, DeeplinkFixture>> = {
  stubhub: stubhubFixture as unknown as DeeplinkFixture,
  vividseats: vividseatsFixture as unknown as DeeplinkFixture,
  tickpick: tickpickFixture as unknown as DeeplinkFixture,
  gametime: gametimeFixture as unknown as DeeplinkFixture,
};

/** Fixture quote for a game slug, or null when the game has no fixture entry. */
export function mockQuoteFor(
  providerId: ProviderId,
  gameSlug: string,
): NormalizedQuote | null {
  const fixture = INVENTORY_FIXTURES[providerId];
  const quote = fixture?.quotes[gameSlug];
  if (!quote) return null;

  return {
    providerId,
    minPriceCents: quote.minPriceCents,
    feesCents: quote.feesCents,
    allInCents: quote.allInCents,
    allInIsEstimate: quote.allInIsEstimate,
    listingCount: quote.listingCount,
    url: quote.url,
    fetchedAt: new Date(quote.fetchedAt),
    isMock: true,
  };
}

/** Fixture deeplink for a game slug, or null when there is no fixture entry. */
export function mockDeeplinkFor(
  providerId: ProviderId,
  gameSlug: string,
): string | null {
  return DEEPLINK_FIXTURES[providerId]?.links[gameSlug] ?? null;
}

/**
 * When a fixture URL is a Mock-Mode placeholder we must not send a real fan to
 * a non-existent host. Callers fall back to the provider's public site instead.
 */
export function isMockUrl(url: string): boolean {
  return url.includes("mock.fantickethub.local");
}
